package io.github.safedecimal.decayingaftermath.compat;
import static org.junit.jupiter.api.Assertions.*;
import java.util.UUID;
import org.junit.jupiter.api.Test;
class MedicalVisualCacheTest {
 @Test void remoteAnatomyAndNativeSerialRemainIdentityBound(){Object level=new Object();var cache=new MedicalVisualCache<Object>();assertTrue(cache.accept(level,level,7,new UUID(1,2),.8f,false,java.util.List.of(0f,0f,.8f,0f,0f,0f),19,0));var visual=cache.live(level,7,new UUID(1,2),true,true,1);assertEquals(19,visual.ragdollSerial());assertEquals(.8f,visual.partBleeding().get(2));assertEquals(0f,visual.partBleeding().get(3));assertNull(cache.live(level,7,new UUID(2,1),true,true,1));}
 private static final UUID PLAYER=new UUID(1,2);
 @Test void remotePlayerNeedsItsOwnMatchingIdentity(){Object level=new Object();var cache=new MedicalVisualCache<Object>();assertTrue(cache.accept(level,level,7,PLAYER,.6f,false,0));assertEquals(.6f,cache.live(level,7,PLAYER,true,true,1).bleeding());assertNull(cache.live(level,8,PLAYER,true,true,1));assertNull(cache.live(level,7,new UUID(3,4),true,true,1));}
 @Test void reusedEntityIdCannotApplyAnotherPlayersSummary(){Object level=new Object();var cache=new MedicalVisualCache<Object>();cache.accept(level,level,7,PLAYER,0,false,0);assertNull(cache.live(level,7,new UUID(9,10),true,true,1));}
 @Test void levelChangeClearsEntriesAndLateOldLevelCallbackIsRejected(){Object old=new Object(),next=new Object();var cache=new MedicalVisualCache<Object>();cache.accept(old,old,7,PLAYER,0,false,0);assertNull(cache.live(next,7,PLAYER,true,true,1));assertEquals(0,cache.size());assertFalse(cache.accept(old,next,7,PLAYER,1,false,2));}
 @Test void expiryAndClockReversalNeverInventStoppedBleeding(){Object level=new Object();var cache=new MedicalVisualCache<Object>();cache.accept(level,level,7,PLAYER,0,false,0);assertNotNull(cache.live(level,7,PLAYER,true,true,MedicalVisualCache.TTL_NANOS));assertNull(cache.live(level,7,PLAYER,true,true,MedicalVisualCache.TTL_NANOS+1));cache.accept(level,level,7,PLAYER,0,false,10);assertNull(cache.live(level,7,PLAYER,true,true,9));}
 @Test void corpsesAndMobsKeepNativeVisualsEvenIfAnIdMatches(){Object level=new Object();var cache=new MedicalVisualCache<Object>();cache.accept(level,level,7,PLAYER,.6f,false,0);assertNull(cache.live(level,7,PLAYER,false,true,1));assertNull(cache.live(level,7,PLAYER,true,false,1));cache.accept(level,level,7,PLAYER,.6f,true,2);assertNull(cache.live(level,7,PLAYER,true,true,3));}
 @Test void disconnectClearsAndRejectsPendingPacket(){Object level=new Object();var cache=new MedicalVisualCache<Object>();cache.accept(level,level,7,PLAYER,0,false,0);cache.reset();assertEquals(0,cache.size());assertNull(cache.live(null,7,PLAYER,true,true,1));assertFalse(cache.accept(level,null,7,PLAYER,.5f,false,2));}
 @Test void malformedSummariesCannotEnterCache(){Object level=new Object();var cache=new MedicalVisualCache<Object>();for(float bad:new float[]{-1,6.1f,Float.NaN,Float.POSITIVE_INFINITY})assertFalse(cache.accept(level,level,7,PLAYER,bad,false,0));assertFalse(cache.accept(level,level,-1,PLAYER,1,false,0));assertFalse(cache.accept(level,level,7,null,1,false,0));assertEquals(0,cache.size());}
 @Test void capacityIsBoundedAndNewestValidPlayerStillAvailable(){Object level=new Object();var cache=new MedicalVisualCache<Object>();for(int i=0;i<300;i++)cache.accept(level,level,i,new UUID(0,i),.5f,false,i);assertEquals(MedicalVisualCache.CAPACITY,cache.size());assertNull(cache.live(level,0,new UUID(0,0),true,true,301));assertNotNull(cache.live(level,299,new UUID(0,299),true,true,301));}
}
